\operatorname{BranchSub}_{CTT}(x,E;z,N)=
\begin{cases}
(x,E),&x=z,\\
(x,E[z:=N]),&x\ne z\land x\notin FV(N),\\
(x',(E[x:=\operatorname{var}(x')])[z:=N]),&x\ne z\land x\in FV(N),
\end{cases}

\mathsf{Rule}_{CTT,\Pi}
=
\{((\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}),
\Gamma\vdash\operatorname{Pi}(x,A,B)\ \mathsf{type})\}
\cup
\{((\Gamma,x:A\vdash M:B),
\Gamma\vdash\operatorname{lam}(x,A,M):\operatorname{Pi}(x,A,B))\}
\cup
\{((\Gamma\vdash F:\operatorname{Pi}(x,A,B),\Gamma\vdash N:A),
\Gamma\vdash\operatorname{app}(F,N):B[x:=N])\}
\cup
\{((\Gamma,x:A\vdash M:B,\Gamma\vdash N:A),
\Gamma\vdash\operatorname{app}(\operatorname{lam}(x,A,M),N)\equiv M[x:=N]:B[x:=N])\}.

\mathsf{Rule}_{CTT,\Sigma}
=
\{((\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}),
\Gamma\vdash\operatorname{Sigma}(x,A,B)\ \mathsf{type})\}
\cup
\{((\Gamma\vdash a:A,\Gamma\vdash b:B[x:=a]),
\Gamma\vdash\operatorname{pair}(a,b):\operatorname{Sigma}(x,A,B))\}
\cup
\{((\Gamma\vdash p:\operatorname{Sigma}(x,A,B)),\Gamma\vdash\operatorname{fst}(p):A)\}
\cup
\{((\Gamma\vdash p:\operatorname{Sigma}(x,A,B)),\Gamma\vdash\operatorname{snd}(p):B[x:=\operatorname{fst}(p)])\}
\cup
\{((\Gamma\vdash a:A,\Gamma\vdash b:B[x:=a]),
\Gamma\vdash\operatorname{fst}(\operatorname{pair}(a,b))\equiv a:A)\}
\cup
\{((\Gamma\vdash a:A,\Gamma\vdash b:B[x:=a]),
\Gamma\vdash\operatorname{snd}(\operatorname{pair}(a,b))\equiv b:B[x:=a])\}.
